    if (!current) byFlow.set(flow.flowKey, { stream, flow, aliases: [] });
    else if (protocolPreference(stream.proto) < protocolPreference(current.stream.proto)) byFlow.set(flow.flowKey, { stream, flow, aliases: [...current.aliases, current.stream.proto] });
